def car_fleet(target, positions, speeds):
    cars = sorted(zip(positions, speeds), reverse=True)
    fleets = 0
    slowest = 0.0
    for pos, spd in cars:
        t = (target - pos) / spd
        if t > slowest:
            fleets += 1
            slowest = t
    return fleets
